from pathlib import Path
p = Path('app/main.py')
s = p.read_text(encoding='utf-8')
s = s.replace('from .observability import setup_logging', 'from .runtime import event, ProcessLock\nfrom .observability import setup_logging')
s = s.replace('    portfolio = await broker.portfolio()', '    portfolio = await broker.portfolio()\n    event(s, "PORTFOLIO", portfolio)')
s = s.replace('    if d.instrument_id not in metadata:', '    event(s, "DECISION", d)\n    if d.action == Action.HOLD:\n        logging.info("HOLD: no order")\n        return\n    if d.instrument_id not in metadata:')
s = s.replace('    start = monotonic()', '    event(s, "ORDER_INTENT", d)\n    start = monotonic()')
s = s.replace('    logging.info("Order submitted: %s", result.order_id)', '    logging.info("Order submitted: %s", result.order_id)\n    event(s, "ORDER_SUBMITTED", result)')
s = s.replace('    journal = Journal(s.journal_path)\n    try:\n        journal.put("last_order", encode(state))', '    event(s, "ORDER_STATE", state)\n    journal = Journal(s.journal_path)\n    try:\n        journal.put("last_order", encode(state))')
s = s.replace('        asyncio.run(asyncio.wait_for(run_once(s, online=args.observe), timeout=max(90, s.ai_timeout + 60)))', '        with ProcessLock():\n            asyncio.run(asyncio.wait_for(run_once(s, online=args.observe), timeout=max(90, s.ai_timeout + 60)))')
p.write_text(s, encoding='utf-8')
p = Path('app/observability.py')
s = p.read_text(encoding='utf-8').replace('import logging', 'import logging\nfrom logging.handlers import RotatingFileHandler').replace("logging.FileHandler('state/bot.log', encoding='utf-8')", "RotatingFileHandler('state/bot.log', maxBytes=5000000, backupCount=5, encoding='utf-8')")
p.write_text(s, encoding='utf-8')
